from lifecycle import pkg_lifecycle_statuses
def show(rows):
    if not rows:
        return "EMPTY"
    return ",".join(f"{row['fun']}={row['lifecycle']}" for row in rows)
print(" || ".join([
    show(pkg_lifecycle_statuses("lifecycle")),
    show(pkg_lifecycle_statuses("lifecycle", which=["deprecated", None])),
    show(pkg_lifecycle_statuses("lifecycle", which="questioning")),
]))
